function small(s){return p(s,{indent:{firstLine:0},spacing:{line:312,after:80},children:undefined});}
function sub(s){return new Paragraph({keepNext:true,spacing:{before:150,after:80,line:312},children:[new TextRun({text:txt(s),bold:true,size:25,color:accent,font:{eastAsia:'SimHei',ascii:'Arial'}})]});}
function cap(s){return new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:60,after:140,line:312},children:[new TextRun({text:txt(s),size:20,color:grey,font:{eastAsia:'SimSun',ascii:'Arial'}})]});}
function img(file,maxH=235){if(!allowed.has(file))throw Error('Disallowed image '+file);const data=fs.readFileSync(path.join(root,file));const dim=imageSize(data);const scale=Math.min(604/dim.width,maxH/dim.height);return new Paragraph({alignment:AlignmentType.CENTER,keepNext:true,spacing:{after:0,line:240},children:[new ImageRun({data,type:dim.type==='jpg'?'jpg':'png',transformation:{width:Math.round(dim.width*scale),height:Math.round(dim.height*scale)},altText:{title:file,description:'原始实拍界面或用户提供图像，按比例缩放'}})]});}
function table(headers,rows,widths){return new Table({width:{size:100,type:WidthType.PERCENTAGE},columnWidths:widths.map(x=>Math.round(9072*x/100)),borders:{top:{style:BorderStyle.SINGLE,size:6,color:accent},bottom:{style:BorderStyle.SINGLE,size:6,color:accent},left:{style:BorderStyle.NONE},right:{style:BorderStyle.NONE},insideHorizontal:{style:BorderStyle.SINGLE,size:2,color:'D8D8D8'},insideVertical:{style:BorderStyle.NONE}},rows:[headers,...rows].map((row,i)=>new TableRow({tableHeader:i===0,cantSplit:true,children:row.map((s,j)=>new TableCell({width:{size:widths[j],type:WidthType.PERCENTAGE},margins:{top:70,bottom:70,left:100,right:100},shading:{type:ShadingType.CLEAR,fill:i===0?'EAF0EC':'FFFFFF'},children:[new Paragraph({spacing:{line:312,after:0},children:[new TextRun({text:txt(s),bold:i===0,size:21,color:'000000',font:{eastAsia:'SimSun',ascii:'Arial'}})]})]}))}))});}
